// Receive payload from the Python Slack listener
// Expected: { channel, channel_name, user, ts, messages }
const body = $input.first().json.body || $input.first().json;

const channel      = body.channel      || 'unknown';
const channelName  = body.channel_name || body.channel || 'unknown';
const user         = body.user         || 'unknown';
const ts           = body.ts           || '';
const messages     = body.messages     || '';

if (!messages.trim()) {
  throw new Error('Empty message received — skipping');
}

// Your Asana project map (OUHSC workspace)
const projects = [
  { gid: '98748256368492',   name: 'Stimulant' },
  { gid: '110638020429313', name: 'Shared Resource mgt' },
  { gid: '184322431079847', name: 'Core' },
  { gid: '184322431079852', name: 'Writing projects' },
  { gid: '189808437708257', name: 'Personal' },
  { gid: '1199886722958318', name: 'Business' },
  { gid: '1201518051754740', name: 'Organize' }
];

const systemPrompt = `You are an expert task extractor. You read Slack messages and extract actionable work items as Asana tasks.

Workspace: OUHSC (GID: 98680584656706)
Auto-assign each task to the most appropriate project. Available projects:
${projects.map(p => `  - "${p.name}" (GID: ${p.gid})`).join('\n')}

Rules:
1. Extract ONLY concrete, actionable tasks — ignore chit-chat, questions, and vague statements
2. If a task is complex or multi-step, add 2-5 subtasks
3. Task names must start with a verb (Fix, Update, Write, Create, Migrate, etc.)
4. If the message contains no actionable tasks, return an empty tasks array
5. Respond ONLY with valid JSON — no markdown, no explanation, no code fences

JSON format:
{
  "tasks": [
    {
      "name": "Verb-first task name",
      "notes": "1-2 sentences of context",
      "project_gid": "GID string",
      "project_name": "Project display name",
      "subtasks": [ { "name": "Subtask name" } ]
    }
  ],
  "summary": "One sentence summary or 'No actionable tasks found'"
}`;

const userPrompt = `Slack channel: #${channelName}\nUser: ${user}\n\nMessage:\n${messages}`;

return [{
  json: {
    channel,
    channelName,
    user,
    ts,
    messages,
    systemPrompt,
    userPrompt
  }
}];

const claudeResponse = $input.first().json;
const promptData = $('Prepare Claude Prompt').first().json;

const textBlock = claudeResponse.content?.find(b => b.type === 'text');
if (!textBlock) {
  throw new Error('No text in Claude response: ' + JSON.stringify(claudeResponse).substring(0, 200));
}

let raw = textBlock.text.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); }
    catch(e2) { throw new Error('Unparseable Claude JSON: ' + raw.substring(0, 200)); }
  } else {
    throw new Error('No JSON in Claude response: ' + raw.substring(0, 200));
  }
}

const tasks = parsed.tasks || [];
const summary = parsed.summary || `Found ${tasks.length} task(s)`;

if (tasks.length === 0) {
  return [{ json: { hasNoTasks: true, summary, channel: promptData.channel, channelName: promptData.channelName, ts: promptData.ts } }];
}

return tasks.map((task, i) => ({
  json: {
    taskIndex: i,
    totalTasks: tasks.length,
    summary,
    name: task.name,
    notes: task.notes || '',
    project_gid: task.project_gid,
    project_name: task.project_name || 'Asana',
    subtasks: task.subtasks || [],
    hasSubtasks: (task.subtasks || []).length > 0,
    channel: promptData.channel,
    channelName: promptData.channelName,
    ts: promptData.ts
  }
}));

// No actionable tasks — log and stop quietly
console.log('No tasks found:', $input.first().json.summary);
return [];

const created = $input.first().json;
const allParsed = $('Parse Claude Response').all();

const taskName = created.name || created.data?.name;
const taskGid  = created.gid  || created.data?.gid;

const matched = allParsed.find(i => i.json.name === taskName);
const subtasks    = matched?.json?.subtasks    || [];
const channelName = matched?.json?.channelName || '';
const ts          = matched?.json?.ts          || '';
const channel     = matched?.json?.channel     || '';

return [{
  json: { taskGid, taskName, subtasks, hasSubtasks: subtasks.length > 0, channelName, channel, ts }
}];

const { taskGid, taskName, subtasks, channelName, channel, ts } = $input.first().json;
return subtasks.map((s, i) => ({
  json: { parentTaskGid: taskGid, parentTaskName: taskName, subtaskName: s.name, subtaskIndex: i, channelName, channel, ts }
}));

const items = $input.all();
const names = items.map(i => i.json.name || i.json.subtaskName || 'Task').filter(Boolean);
return [{ json: { success: true, tasks_created: items.length, task_names: names } }];

